namespace PlatformApi.Models;

public enum RegistrationLinkType
{
    /// <summary>Onboards a brand-new client: creates their organization + first location.</summary>
    NewOrganization = 0,

    /// <summary>Adds an additional location to an existing organization.</summary>
    NewLocation = 1,
}

public static class RegistrationLinkStatus
{
    public const string Active = "active";
    public const string Used = "used";
    public const string Revoked = "revoked";
}

/// <summary>
/// A one-time provisioning link generated by the platform console after a subscription is
/// paid. Redeemed by the client in the restaurant app to register / add a location.
/// Lives in the HQ-owned <c>platform_registration_links</c> table.
/// </summary>
public class RegistrationLink
{
    public Guid Id { get; set; } = Guid.NewGuid();
    public Guid Token { get; set; } = Guid.NewGuid();
    public RegistrationLinkType Type { get; set; }

    /// <summary>Set when <see cref="Type"/> is <see cref="RegistrationLinkType.NewLocation"/>.</summary>
    public Guid? OrganizationId { get; set; }

    /// <summary>Free-text note (intended org/location name).</summary>
    public string? Label { get; set; }
    public string? IntendedEmail { get; set; }

    public string Status { get; set; } = RegistrationLinkStatus.Active;
    public DateTime ExpiresAt { get; set; }
    public Guid CreatedByPlatformAdminId { get; set; }
    public DateTime CreatedAt { get; set; } = DateTime.UtcNow;
    public DateTime? UsedAt { get; set; }
}
